import { createHash } from 'node:crypto';
import { existsSync, readFileSync } from 'node:fs';
import { fileURLToPath } from 'node:url';
import { expect, test } from '@playwright/test';
import { CHAPTERS } from '../../src/data/brand';
import { catalogue } from '../../src/i18n';

const copy = catalogue('en').brand;

/**
 * The identity document as a file - phases.md 8.10d.
 *
 * **The failure this exists for is a PDF that no longer says what the page says.** The
 * document is generated by `npm run pdf` and committed, so the moment somebody edits a
 * sentence in `brand.ts`, a colour in `tokens.css` or a curve in `motion/tokens.ts` and
 * does not re-run the script, `/brand` and `/brand/sonaru-brand.pdf` are two different
 * identity documents. Nothing about that shows on the site - the page is right, the
 * download still works, and the only person who sees the old one is a designer who opened
 * the file instead of the page.
 *
 * **This is a stronger guard than `press-assets.spec.ts` could write**, and the difference
 * is worth stating: that file has to admit its screenshot hashes guard nothing, because
 * their inputs live in the iOS repo and CI does not check it out. Every input to this PDF
 * is in this repo, so the hash below is recomputed on every run and a stale document is a
 * red build.
 */

const BRAND = new URL('../../public/brand/', import.meta.url);
const ROOT = new URL('../../', import.meta.url);

const manifest = JSON.parse(readFileSync(new URL('manifest.json', BRAND), 'utf8')) as {
  file: string;
  bytes: number;
  pages: number;
  inputs: Record<string, string>;
};

/** The same 16 hex characters `build-brand-pdf.mjs` writes. */
function hashOf(path: string): string {
  return createHash('sha256')
    .update(readFileSync(fileURLToPath(new URL(path, ROOT)), 'utf8'))
    .digest('hex')
    .slice(0, 16);
}

test('the document exists and is the size the page advertises', () => {
  const path = fileURLToPath(new URL(manifest.file, BRAND));
  expect(existsSync(path), `public/brand/${manifest.file}`).toBe(true);
  // `/brand` and `/press` both print this number. A manifest that disagrees with the file
  // is a download that says one weight and delivers another.
  expect(readFileSync(path).length).toBe(manifest.bytes);
});

test('the document was generated from the sources as they stand now', () => {
  // Recomputed, never trusted - the whole point of the manifest.
  for (const [path, hash] of Object.entries(manifest.inputs)) {
    expect(hashOf(path), `${path} changed since the last \`npm run pdf\``).toBe(hash);
  }
});

test('every chapter of the page is a bookmark in the document', () => {
  /*
   * `outline: true` turns the eight `<h2>`s into the reader's own chapter list - the
   * sidebar `/brand` deliberately does not have on screen, and the only navigation a
   * 22-page PDF gets. It is an option on one call, which means it is exactly the kind of
   * thing that survives a refactor with nothing to show for it: the document still
   * generates, still looks right, and has quietly become unnavigable.
   */
  const pdf = readFileSync(fileURLToPath(new URL(manifest.file, BRAND))).toString('latin1');
  expect(pdf, 'the PDF has no outline at all').toContain('/Outlines');
  const titles = [...pdf.matchAll(/\/Title\s*\(((?:[^()\\]|\\.)*)\)/g)].map((match) => match[1]);
  for (const chapter of CHAPTERS) {
    const title = copy.chapters[chapter.id];
    expect(titles, `"${title}" is a chapter of the page`).toContain(title);
  }
});

test('the page count is real', () => {
  // A document of zero pages is a generator that silently wrote a header and stopped.
  expect(manifest.pages).toBeGreaterThan(1);
});

test('the download is offered by the built page, not just by the dev server', () => {
  /*
   * 8.10c's lesson: assert anything about shipped bytes against `dist/`, because
   * `astro dev` injects an HMR client and a dev toolbar and an e2e test cannot tell the
   * difference. Both routes offer this file and both are built pages.
   */
  for (const route of ['brand', 'press']) {
    const html = readFileSync(fileURLToPath(new URL(`dist/${route}/index.html`, ROOT)), 'utf8');
    expect(html, `dist/${route}/index.html`).toContain(`/brand/${manifest.file}`);
  }
});
